def posicionar_contador(apps, schema_editor):
    """Põe o contador onde a numeração já chegou, por clínica.

    Nascido em zero, o próximo cadastro receberia 000001 — número que a
    base existente já usa —, e a gravação seria recusada pela restrição de
    unicidade. O contador tem de partir do maior número já emitido.
    """
    alias = schema_editor.connection.alias
    Patient = apps.get_model('patients', 'Patient')
    Sequence = apps.get_model('patients', 'PatientNumberSequence')

    maior = {}
    valores = (
        Patient.objects.using(alias)
        .exclude(record_number='')
        .values_list('tenant_id', 'record_number')
    )
    for tenant_id, numero in valores:
        digits = ''.join(c for c in numero if c.isdigit())
        if digits:
            maior[tenant_id] = max(maior.get(tenant_id, 0), int(digits))

    for tenant_id, ultimo in maior.items():
        Sequence.objects.using(alias).update_or_create(
            tenant_id=tenant_id, defaults={'last_number': ultimo},
        )


